"""Serving-side index: one on-disk index, and filling it from a parquet artifact.

A :class:`LocalIndex` owns one index folder: the vector store and the
``meta.json`` stamping which corpus version and embedding config it holds. The
folder is ``index_cache_dir/<corpus>/<key>``, where the key hashes
``(embed_engine, embed_model)``: each corpus gets its own folder, and a new
version of the same corpus rebuilds in place.

Both ways of filling an index go through :meth:`LocalIndex.is_current` and
:meth:`LocalIndex.replace`: :func:`ingest_vector_artifact` here loads
precomputed vectors (the copilot's path, no embedding), and ``sync_index`` in
the offline build pipeline embeds a corpus.
"""

import hashlib
import json
import re
from pathlib import Path
from typing import Any, Dict, List, Optional

import structlog

from rasa.builder.document_retrieval.local.config import (
    LocalRetrievalConfig,
    SearchMode,
)
from rasa.builder.document_retrieval.local.lancedb_store import LanceDBVectorStore
from rasa.builder.document_retrieval.local.parquet_artifact import (
    read_parquet_meta,
    read_vectors_parquet,
)
from rasa.builder.document_retrieval.local.vector_store import BaseVectorStore

structlogger = structlog.get_logger()

_META_FILENAME = "meta.json"

# A corpus name becomes a folder name, so it may not contain path separators.
_CORPUS_NAME_RE = re.compile(r"^[a-z0-9][a-z0-9_-]*$")


class IndexConfigMismatch(ValueError):
    """Raised when an existing index was built with incompatible config."""


class LocalIndex:
    """One on-disk index: a vector store plus the ``meta.json`` that stamps it.

    The folder is computed once, here, so the store and its stamp always live
    in the same place. Constructing an index does no I/O.
    """

    def __init__(self, cfg: LocalRetrievalConfig, *, corpus: str) -> None:
        """Locate the index for ``corpus`` under ``cfg.index_cache_dir``.

        Args:
            cfg: Retrieval config; its embedding config keys the folder.
            corpus: Name of the corpus the index holds, e.g. ``"rasa-docs"``.

        Raises:
            ValueError: If ``corpus`` is not a plain lowercase name, or the
                configured vector store is unknown.
        """
        if not _CORPUS_NAME_RE.match(corpus):
            raise ValueError(
                f"Invalid corpus name {corpus!r}: use lowercase letters, digits, "
                "'-' and '_'."
            )
        self._cfg = cfg
        self._corpus = corpus
        self._key = _index_key(cfg)
        self._path = Path(cfg.index_cache_dir) / corpus / self._key
        self._store = _build_store(cfg.vector_store, self._path)

    @property
    def config(self) -> LocalRetrievalConfig:
        """The retrieval config this index was built for."""
        return self._cfg

    @property
    def corpus(self) -> str:
        """Name of the corpus the index holds."""
        return self._corpus

    @property
    def key(self) -> str:
        """Short hash of the embedding config, used as the folder name."""
        return self._key

    @property
    def path(self) -> Path:
        """Folder holding the vector store and its ``meta.json``."""
        return self._path

    @property
    def store(self) -> BaseVectorStore:
        """The vector store that queries run against."""
        return self._store

    def is_current(self, corpus_version: str) -> bool:
        """Whether the store exists and ``meta.json`` records ``corpus_version``."""
        return self._store.exists() and self._stamped_corpus_version() == corpus_version

    def replace(
        self,
        rows: List[Dict[str, Any]],
        *,
        corpus_version: str,
        document_count: int,
        embed_dim: int,
    ) -> None:
        """Replace the store's contents with ``rows`` and stamp ``meta.json``.

        Builds the full-text index too when the config serves hybrid search.

        Args:
            rows: Embedded chunk rows, as produced by ``Chunk.to_row``.
            corpus_version: Snapshot the rows were built from.
            document_count: Number of source documents behind the rows.
            embed_dim: Dimension of the rows' vectors.
        """
        if self._store.exists():
            self._store.drop()
        self._store.add(rows)
        # FTS index backs hybrid search only; skip the build cost when serving vector.
        if self._cfg.search_mode is SearchMode.HYBRID:
            self._store.ensure_text_index()
        self._write_meta(corpus_version, document_count, len(rows), embed_dim)

    def _meta_path(self) -> Path:
        return self._path / _META_FILENAME

    def _stamped_corpus_version(self) -> Optional[str]:
        """Corpus version recorded in ``meta.json``, if any."""
        meta_path = self._meta_path()
        if not meta_path.exists():
            return None
        return json.loads(meta_path.read_text()).get("corpus_version")

    def _write_meta(
        self,
        corpus_version: str,
        document_count: int,
        chunk_count: int,
        embed_dim: int,
    ) -> None:
        """Stamp what this index represents (audit + consistency check)."""
        self._path.mkdir(parents=True, exist_ok=True)
        self._meta_path().write_text(
            json.dumps(
                {
                    "embed_engine": self._cfg.embedder.embed_engine,
                    "embed_model": self._cfg.embedder.embed_model,
                    "embed_dim": embed_dim,
                    "corpus_version": corpus_version,
                    "document_count": document_count,
                    "chunk_count": chunk_count,
                },
                indent=2,
            )
        )


def _index_key(cfg: LocalRetrievalConfig) -> str:
    """Stable short hash over the fields that define the index's vector space.

    Excludes the corpus version: a new version rebuilds in place, not into a
    separate index directory. Chunking is code-defined, so it is not part of the key.
    """
    payload = {
        "embed_engine": cfg.embedder.embed_engine,
        "embed_model": cfg.embedder.embed_model,
    }
    canonical = json.dumps(payload, sort_keys=True)
    digest = hashlib.sha1(canonical.encode("utf-8"), usedforsecurity=False)
    return digest.hexdigest()[:16]


def _build_store(vector_store: str, location: Path) -> BaseVectorStore:
    """Construct the configured vector store backend at ``location``."""
    if vector_store == "lancedb":
        return LanceDBVectorStore(str(location))
    raise ValueError(f"Unknown vector_store: {vector_store}")


def _assert_artifact_matches(
    cfg: LocalRetrievalConfig, embed_dim: int, meta: Dict[str, Any]
) -> None:
    """Refuse to ingest an artifact the serving side cannot query against.

    Enforces the embedding-model parity invariant (engine/model/dim).
    """
    expected = {
        "embed_engine": cfg.embedder.embed_engine,
        "embed_model": cfg.embedder.embed_model,
        "embed_dim": embed_dim,
    }
    mismatches = {k: (meta.get(k), v) for k, v in expected.items() if meta.get(k) != v}
    if mismatches:
        raise IndexConfigMismatch(
            "Vector artifact was built with config the serving backend cannot "
            f"query against (field: (artifact, serving)) {mismatches}. Rebuild "
            "the artifact or align the serving config."
        )


def ingest_vector_artifact(
    index: LocalIndex, parquet_path: str, embed_dim: int
) -> None:
    """Load precomputed vectors from a parquet artifact into ``index``.

    Only the parquet footer is read until the rows are actually needed: an
    incompatible artifact raises, and a current index is left as is, before
    any rows are loaded.

    Args:
        index: The index to fill.
        parquet_path: Path to the prebuilt parquet vector artifact.
        embed_dim: Dimension of the query-time embedder, checked against the
            artifact's.

    Raises:
        IndexConfigMismatch: If the artifact was built with an embedding config
            the index cannot be queried with.
    """
    path = Path(parquet_path)
    meta = read_parquet_meta(path)
    _assert_artifact_matches(index.config, embed_dim, meta)
    corpus_version = str(meta.get("corpus_version", ""))

    if index.is_current(corpus_version):
        structlogger.info(
            "vector_artifact.ingest_noop",
            corpus=index.corpus,
            key=index.key,
            corpus_version=corpus_version,
        )
        return

    rows = read_vectors_parquet(path)
    index.replace(
        rows,
        corpus_version=corpus_version,
        document_count=int(meta.get("document_count", 0)),
        embed_dim=embed_dim,
    )
    structlogger.info(
        "vector_artifact.ingested",
        corpus=index.corpus,
        key=index.key,
        corpus_version=corpus_version,
        chunk_count=len(rows),
        embed_dim=embed_dim,
    )
